import { DatabaseSync } from 'node:sqlite';
import { mkdirSync } from 'node:fs';
import { dirname } from 'node:path';

/** One row of the `jobs` table. Shared by the server and the worker. */
export interface JobRow {
  seq: number;
  id: string;
  status: 'queued' | 'running' | 'completed' | 'failed';
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  idempotency_key: string | null;
  /** Earliest time (ms since epoch) at which a queued job may be picked up. */
  run_after: number;
  created_at: string;
  updated_at: string;
}

/** Opens the SQLite database shared by the server and worker processes and ensures the schema exists. */
export function openDatabase(path: string = process.env.DATABASE_PATH ?? 'data/jobs.db'): DatabaseSync {
  if (path !== ':memory:') mkdirSync(dirname(path), { recursive: true });
  const db = new DatabaseSync(path);
  // busy_timeout first: switching to WAL takes a brief exclusive lock, and the server and worker
  // open the same database at once, so the loser must wait rather than fail.
  db.exec('PRAGMA busy_timeout = 5000; PRAGMA journal_mode = WAL; PRAGMA synchronous = FULL;');
  initSchema(db);
  return db;
}

function initSchema(db: DatabaseSync): void {
  db.exec(`
    CREATE TABLE IF NOT EXISTS jobs (
      seq INTEGER PRIMARY KEY AUTOINCREMENT,
      id TEXT NOT NULL UNIQUE,
      status TEXT NOT NULL CHECK (status IN ('queued', 'running', 'completed', 'failed')),
      input TEXT NOT NULL,
      steps INTEGER NOT NULL,
      fail_attempts INTEGER NOT NULL,
      attempts INTEGER NOT NULL DEFAULT 0,
      progress_completed INTEGER NOT NULL DEFAULT 0,
      result_output TEXT,
      error TEXT,
      idempotency_key TEXT UNIQUE,
      run_after INTEGER NOT NULL DEFAULT 0,
      created_at TEXT NOT NULL,
      updated_at TEXT NOT NULL
    );
    CREATE INDEX IF NOT EXISTS jobs_queue ON jobs (status, run_after, seq);
    CREATE TABLE IF NOT EXISTS worker_heartbeat (
      id INTEGER PRIMARY KEY CHECK (id = 1),
      beat_at INTEGER NOT NULL
    );
  `);
}
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { randomUUID } from 'node:crypto';
import { readFileSync } from 'node:fs';
import { openDatabase, type JobRow } from './db.ts';

const MAX_BODY_BYTES = 64 * 1024;
const WORKER_FRESH_MS = 3000;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const IDEMPOTENCY_KEY_RE = /^[A-Za-z0-9_-]{1,128}$/;

interface FieldError {
  field: string;
  message: string;
}

interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');

const insertJob = db.prepare(
  `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, idempotency_key, run_after, created_at, updated_at)
   VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, 0, ?, ?)`,
);
const jobById = db.prepare('SELECT * FROM jobs WHERE id = ?');
const jobByKey = db.prepare('SELECT * FROM jobs WHERE idempotency_key = ?');
const listJobs = db.prepare('SELECT * FROM jobs ORDER BY seq DESC');
const workerBeat = db.prepare('SELECT beat_at FROM worker_heartbeat WHERE id = 1');

function send(res: ServerResponse, status: number, body: unknown, headers: Record<string, string> = {}): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8', ...headers });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function toJob(row: JobRow) {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

function mediaType(req: IncomingMessage): string {
  const value = req.headers['content-type'];
  return typeof value === 'string' ? value.split(';')[0].trim().toLowerCase() : '';
}

function readBody(req: IncomingMessage): Promise<string | null> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? null : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

const isPlainObject = (v: unknown): v is Record<string, unknown> => typeof v === 'object' && v !== null && !Array.isArray(v);
const isIntIn = (v: unknown, min: number, max: number): v is number => typeof v === 'number' && Number.isInteger(v) && v >= min && v <= max;

/** Validates a parsed body, collecting one entry per offending field. */
function validate(body: Record<string, unknown>, fields: FieldError[]): Submission | undefined {
  const before = fields.length;
  for (const key of Object.keys(body)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'unknown field' });
  }
  const input = body.input;
  const steps = body.steps === undefined ? 5 : body.steps;
  const failAttempts = body.failAttempts === undefined ? 0 : body.failAttempts;
  if (typeof input !== 'string' || input.length < 1 || input.length > 1000 || input.trim() === '') {
    fields.push({ field: 'input', message: 'must be a string of 1 to 1000 characters that is not only whitespace' });
  }
  if (!isIntIn(steps, 1, 20)) fields.push({ field: 'steps', message: 'must be an integer from 1 to 20' });
  if (!isIntIn(failAttempts, 0, 5)) fields.push({ field: 'failAttempts', message: 'must be an integer from 0 to 5' });
  if (fields.length > before || typeof input !== 'string' || !isIntIn(steps, 1, 20) || !isIntIn(failAttempts, 0, 5)) return undefined;
  return { input, steps, failAttempts };
}

function sameSubmission(job: JobRow, sub: Submission): boolean {
  return job.input === sub.input && job.steps === sub.steps && job.fail_attempts === sub.failAttempts;
}

/** Creates the job, or returns the existing one for a known idempotency key. Atomic across processes. */
function createOrReplay(sub: Submission, key: string | null): { job: JobRow; created: boolean } | 'conflict' {
  db.exec('BEGIN IMMEDIATE');
  try {
    if (key !== null) {
      const existing = jobByKey.get(key) as unknown as JobRow | undefined;
      if (existing) {
        db.exec('COMMIT');
        return sameSubmission(existing, sub) ? { job: existing, created: false } : 'conflict';
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    insertJob.run(id, sub.input, sub.steps, sub.failAttempts, key, now, now);
    const job = jobById.get(id) as unknown as JobRow;
    db.exec('COMMIT');
    return { job, created: true };
  } catch (e) {
    db.exec('ROLLBACK');
    throw e;
  }
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const raw = await readBody(req);
  const fields: FieldError[] = [];

  const keyHeader = req.headers['idempotency-key'];
  let key: string | null = null;
  if (keyHeader !== undefined) {
    if (typeof keyHeader === 'string' && IDEMPOTENCY_KEY_RE.test(keyHeader)) key = keyHeader;
    else fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  let body: Record<string, unknown> | undefined;
  if (mediaType(req) !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (raw === null) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(raw);
    } catch {
      fields.push({ field: 'body', message: 'malformed JSON' });
    }
    if (parsed !== undefined) {
      if (isPlainObject(parsed)) body = parsed;
      else fields.push({ field: 'body', message: 'must be a JSON object' });
    }
  }

  const sub = body ? validate(body, fields) : undefined;
  if (fields.length > 0 || !sub) {
    sendError(res, 400, 'invalid_request', `Invalid request: ${fields.map((f) => f.field).join(', ')}.`, fields);
    return;
  }

  const result = createOrReplay(sub, key);
  if (result === 'conflict') {
    sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
    return;
  }
  send(res, result.created ? 201 : 200, toJob(result.job));
}

function handleHealth(res: ServerResponse): void {
  const row = workerBeat.get() as { beat_at: number } | undefined;
  const up = row !== undefined && Date.now() - row.beat_at <= WORKER_FRESH_MS;
  send(res, 200, { status: 'ok', worker: up ? 'up' : 'down' });
}

function methodNotAllowed(res: ServerResponse, allowed: string): void {
  send(
    res,
    405,
    { error: { code: 'method_not_allowed', message: `Method not allowed. Use ${allowed}.` } },
    { allow: allowed },
  );
}

async function route(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? '';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method === 'GET') return handleHealth(res);
    return methodNotAllowed(res, 'GET');
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: (listJobs.all() as unknown as JobRow[]).map(toJob) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, 'GET, POST');
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, 'GET');
    let id: string;
    try {
      id = decodeURIComponent(match[1]);
    } catch {
      return sendError(res, 404, 'not_found', 'Job not found.');
    }
    const row = jobById.get(id) as unknown as JobRow | undefined;
    if (!row) return sendError(res, 404, 'not_found', 'Job not found.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'Not found.');
}

const port = Number(process.env.PORT ?? 3000);
const server = createServer((req, res) => {
  route(req, res).catch((e: unknown) => {
    console.error('request failed:', e instanceof Error ? e.stack ?? e.message : String(e));
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Internal server error.');
  });
});

server.listen(port, () => console.log(`server listening on ${port}`));

function shutdown(): void {
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, type JobRow } from './db.ts';

const STEP_MS = 100;
const POLL_MS = 200;
const HEARTBEAT_MS = 1000;
const MAX_ATTEMPTS = 3;
const RETRY_DELAY_MS = 500;

const db = openDatabase();
const stop = new AbortController();
let stopping = false;

const nextQueued = db.prepare(`SELECT * FROM jobs WHERE status = 'queued' AND run_after <= ? ORDER BY seq LIMIT 1`);
const claim = db.prepare(
  `UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ?
   WHERE id = ? AND status = 'queued' RETURNING attempts`,
);
const setProgress = db.prepare(`UPDATE jobs SET progress_completed = ?, updated_at = ? WHERE id = ?`);
const complete = db.prepare(
  `UPDATE jobs SET status = 'completed', progress_completed = steps, result_output = ?, error = NULL, updated_at = ? WHERE id = ?`,
);
const fail = db.prepare(
  `UPDATE jobs SET status = 'failed', result_output = NULL, error = 'transient failure', updated_at = ? WHERE id = ?`,
);
const requeue = db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = ?, updated_at = ? WHERE id = ?`,
);
const recoverRunning = db.prepare(
  `UPDATE jobs SET status = 'queued', progress_completed = 0, run_after = 0, updated_at = ? WHERE status = 'running'`,
);
const beat = db.prepare(
  `INSERT INTO worker_heartbeat (id, beat_at) VALUES (1, ?) ON CONFLICT(id) DO UPDATE SET beat_at = excluded.beat_at`,
);

const nowIso = () => new Date().toISOString();

/** Sleeps for `ms`, returning early when shutdown is requested. */
async function pause(ms: number): Promise<void> {
  try {
    await sleep(ms, undefined, { signal: stop.signal });
  } catch {
    // aborted by shutdown
  }
}

/** Runs one attempt of a claimed job. Returns early, leaving the job `running`, if shutdown is requested. */
async function runAttempt(job: JobRow, attempt: number): Promise<void> {
  if (attempt <= job.fail_attempts) {
    // Simulated transient failure: fails at the first step, before any progress.
    await pause(STEP_MS);
    if (stopping) return;
    if (attempt < MAX_ATTEMPTS) requeue.run(Date.now() + RETRY_DELAY_MS, nowIso(), job.id);
    else fail.run(nowIso(), job.id);
    return;
  }
  for (let completed = 1; completed <= job.steps; completed++) {
    await pause(STEP_MS);
    if (stopping) return;
    setProgress.run(completed, nowIso(), job.id);
  }
  complete.run(job.input.toUpperCase(), nowIso(), job.id);
}

function heartbeat(): void {
  try {
    beat.run(Date.now());
  } catch (e) {
    console.error('heartbeat failed:', e instanceof Error ? e.message : String(e));
  }
}

for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
    stop.abort();
  });
}

// A job left `running` by a previous worker that died is processed again from the start.
recoverRunning.run(nowIso());
heartbeat();
const heartbeatTimer = setInterval(heartbeat, HEARTBEAT_MS);

console.log('worker started');
while (!stopping) {
  try {
    const job = nextQueued.get(Date.now()) as unknown as JobRow | undefined;
    if (!job) {
      await pause(POLL_MS);
      continue;
    }
    const claimed = claim.get(nowIso(), job.id) as { attempts: number } | undefined;
    if (!claimed) continue;
    await runAttempt(job, claimed.attempts);
  } catch (e) {
    console.error('worker error:', e instanceof Error ? e.stack ?? e.message : String(e));
    await pause(1000);
  }
}

clearInterval(heartbeatTimer);
// A stopped worker reports "down" immediately rather than after the 3-second staleness window.
db.prepare('UPDATE worker_heartbeat SET beat_at = 0 WHERE id = 1').run();
db.close();
console.log('worker stopped');
process.exit(0);
