<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width, initial-scale=1">
  <title>Job tracker</title>
  <style>
    body { font-family: system-ui, sans-serif; margin: 2rem auto; max-width: 48rem; padding: 0 1rem; color: #222; }
    form { display: flex; flex-wrap: wrap; gap: 0.75rem; align-items: flex-end; }
    label { display: flex; flex-direction: column; font-size: 0.9rem; }
    input[type="text"] { padding: 0.35rem; min-width: 0; }
    [data-testid="job-input"] { width: 24rem; }
    [data-testid="job-steps"], [data-testid="job-fail-attempts"] { width: 6rem; }
    button { padding: 0.4rem 1rem; }
    [data-testid="form-error"] { color: #b00020; margin: 1rem 0; min-height: 1em; }
    [data-testid="job-list"] { list-style: none; padding: 0; }
    [data-testid="job-item"] { border: 1px solid #ddd; border-radius: 4px; padding: 0.5rem 0.75rem; margin-bottom: 0.5rem; }
    .job-input { font-weight: 600; word-break: break-all; }
    .job-meta { font-size: 0.9rem; color: #555; display: flex; gap: 1rem; flex-wrap: wrap; }
    [data-testid="job-result"] { font-family: ui-monospace, monospace; word-break: break-all; }
  </style>
</head>
<body>
  <h1>Job tracker</h1>

  <form data-testid="job-form" id="job-form">
    <label>Input
      <input data-testid="job-input" type="text" name="input" autocomplete="off">
    </label>
    <label>Steps
      <input data-testid="job-steps" type="text" name="steps" inputmode="numeric" value="5">
    </label>
    <label>Fail attempts
      <input data-testid="job-fail-attempts" type="text" name="failAttempts" inputmode="numeric" value="0">
    </label>
    <button data-testid="job-submit" type="submit">Submit</button>
  </form>

  <div data-testid="form-error" role="alert" id="form-error"></div>

  <ul data-testid="job-list" id="job-list"></ul>

  <script>
    (function () {
      var form = document.getElementById('job-form');
      var inputEl = document.querySelector('[data-testid="job-input"]');
      var stepsEl = document.querySelector('[data-testid="job-steps"]');
      var failEl = document.querySelector('[data-testid="job-fail-attempts"]');
      var submitBtn = document.querySelector('[data-testid="job-submit"]');
      var errorEl = document.getElementById('form-error');
      var listEl = document.getElementById('job-list');
      var items = new Map();

      // Numeric text is sent as a number; empty text is omitted so the server default applies;
      // anything else is sent as text so the API rejects it and names the field.
      function fieldValue(raw) {
        var v = raw.trim();
        if (v === '') return undefined;
        return /^[+-]?\d+(\.\d+)?$/.test(v) ? Number(v) : v;
      }

      function showError(data, fallback) {
        var err = data && data.error;
        if (!err) {
          errorEl.textContent = fallback;
          return;
        }
        var text = err.message || 'Submission rejected.';
        if (Array.isArray(err.fields) && err.fields.length > 0) {
          text += ' ' + err.fields.map(function (f) { return f.field + ': ' + f.message; }).join('; ') + '.';
        }
        errorEl.textContent = text;
      }

      function createItem(id) {
        var li = document.createElement('li');
        li.setAttribute('data-testid', 'job-item');
        li.setAttribute('data-job-id', id);
        var input = document.createElement('div');
        input.className = 'job-input';
        var meta = document.createElement('div');
        meta.className = 'job-meta';
        ['job-status', 'job-progress'].forEach(function (testid) {
          var s = document.createElement('span');
          s.setAttribute('data-testid', testid);
          meta.appendChild(s);
        });
        var result = document.createElement('div');
        result.setAttribute('data-testid', 'job-result');
        li.append(input, meta, result);
        return li;
      }

      function updateItem(li, job) {
        li.firstChild.textContent = job.input;
        li.querySelector('[data-testid="job-status"]').textContent = job.status;
        li.querySelector('[data-testid="job-progress"]').textContent = job.progress.completed + '/' + job.progress.total;
        var text = '';
        if (job.status === 'completed' && job.result) text = job.result.output;
        else if (job.status === 'failed' && job.error) text = job.error;
        li.querySelector('[data-testid="job-result"]').textContent = text;
      }

      function render(jobs) {
        var seen = new Set();
        var nodes = jobs.map(function (job) {
          seen.add(job.id);
          var li = items.get(job.id);
          if (!li) {
            li = createItem(job.id);
            items.set(job.id, li);
          }
          updateItem(li, job);
          return li;
        });
        items.forEach(function (li, id) {
          if (!seen.has(id)) {
            li.remove();
            items.delete(id);
          }
        });
        listEl.replaceChildren.apply(listEl, nodes);
      }

      function refresh() {
        return fetch('/api/jobs', { cache: 'no-store' })
          .then(function (res) { return res.ok ? res.json() : null; })
          .then(function (data) { if (data && Array.isArray(data.jobs)) render(data.jobs); })
          .catch(function () { /* keep the last list; retry on the next tick */ });
      }

      form.addEventListener('submit', function (e) {
        e.preventDefault();
        errorEl.textContent = '';
        var body = { input: inputEl.value };
        var steps = fieldValue(stepsEl.value);
        var failAttempts = fieldValue(failEl.value);
        if (steps !== undefined) body.steps = steps;
        if (failAttempts !== undefined) body.failAttempts = failAttempts;
        submitBtn.disabled = true;
        fetch('/api/jobs', {
          method: 'POST',
          headers: { 'content-type': 'application/json' },
          body: JSON.stringify(body),
        })
          .then(function (res) {
            return res.json().catch(function () { return null; }).then(function (data) {
              if (res.status === 200 || res.status === 201) {
                inputEl.value = '';
                return refresh();
              }
              showError(data, 'Submission failed (HTTP ' + res.status + ').');
            });
          })
          .catch(function () { errorEl.textContent = 'Could not reach the server.'; })
          .then(function () { submitBtn.disabled = false; });
      });

      refresh();
      setInterval(refresh, 1000);
    })();
  </script>
</body>
</html>

